import { Flow, FlowObject, wfa, trigger, action } from '@servicenow/sdk/automation'
import { DateTimeColumn, StringColumn, BooleanColumn, IntegerColumn } from '@servicenow/sdk/core'

Flow(
    {
        $id: Now.ID['test_flow_for_reference_column_in_flow_object'],
        name: 'Test flow for Object containing ReferenceColumn in Flow Variable',
        flowVariables: {
            employee: FlowObject({
                fields: {
                    joining_date: DateTimeColumn({
                        label: 'Joining Date',
                    }),
                    name: StringColumn({
                        label: 'Name',
                    }),
                    remote: BooleanColumn({
                        label: 'Remote',
                        default: 'false',
                    }),
                    salary: IntegerColumn({
                        label: 'Salary',
                    }),
                },
                label: 'Employee',
            }),
        },
    },
    wfa.trigger(
        trigger.scheduled.daily,
        {
            $id: Now.ID['test_flow_for_reference_column_in_flow_object_trigger'],
        },
        {
            time: Time({
                hours: 15,
                minutes: 30,
            }),
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['test_flow_for_reference_column_in_flow_object_step1'],
                annotation: 'Log employee details',
            },
            {
                log_level: 'info',
                log_message: `Employee details : Name = ${wfa.dataPill(_params.flowVariables.employee.name, 'string')}`,
            }
        )
    }
)
